@startuml

class Car {
  + licensePlate : string
}

class Owner {
  + name : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class RideHail {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
  + numberOfPassengers : int
  + fee : double
  + requestType : string
}

class RideShare {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
  + upfrontNegotiatedFee : double
}

class Customer {
  + name : string
}

class RideHailCustomer {
  + name : string
}

class RideShareCustomer {
  + name : string
}

Car "1" -- "0..*" Accident : experiences
Car "0..1" -- "1" Owner : ownedBy
Car "1" -- "*" RideHail : provides
Car "1" -- "*" RideShare : provides

RideHail "*" -- "1" RideHailCustomer : leadCustomer
RideShare "*" -- "1..10" RideShareCustomer : passengers

@enduml

